INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('2ead3725-7151-4b8d-9d93-e279e7f30be1', '1c40c9dd-e417-443a-8e05-dd4c6e99a1f5', 'A 23-year-old male patient A 45-year-old patient with confirmed H. pylori on stool antigen test has no known drug allergies and has not taken macrolide antibiotics previously. (Case Ref: GASTROINTESTINAL-1229). Relevant physiological and medication history have been reviewed.', 'Which 7-day eradication regimen is recommended first-line by NICE?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('37aca6b1-09d1-4dd6-bf35-a39a87390705', '1c40c9dd-e417-443a-8e05-dd4c6e99a1f5', 'A', 'PPI twice daily + Amoxicillin 1 g twice daily + Clarithromycin 500 mg twice daily for 7 days', 1, 'Correct. Standard UK first-line triple eradication consists of a full-dose PPI bd + amoxicillin 1g bd + clarithromycin 500mg bd (or metronidazole 400mg bd) for 7 days.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('9d26a9e5-314d-4ca5-8328-a8039ad7337b', '1c40c9dd-e417-443a-8e05-dd4c6e99a1f5', 'B', 'PPI once daily + Amoxicillin 500 mg TDS for 14 days without second antibiotic', 0, 'Sub-optimal. Dual therapy has poor eradication rates; two synergic antibiotics plus twice-daily acid suppression are essential.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c434bbe6-9707-43bd-9a33-082475fd9eb5', '1c40c9dd-e417-443a-8e05-dd4c6e99a1f5', 'C', 'Prescribe Clarithromycin in a patient taking concurrent Simvastatin 40 mg', 0, 'Dangerous interaction. Strong CYP3A4 inhibition increases statin exposure exponentially, causing rhabdomyolysis.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('8504b1c6-e312-4828-b7a3-03152d908881', '1c40c9dd-e417-443a-8e05-dd4c6e99a1f5', 'D', 'Triple therapy containing Ranitidine instead of PPI', 0, 'Deprecated and unavailable; ranitidine was withdrawn globally due to NDMA impurities.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('ee71d442-be4e-411d-aba1-214576ddd093', '1c40c9dd-e417-443a-8e05-dd4c6e99a1f5', 'E', 'Retest H. pylori via stool antigen 2 days after completing antibiotics', 0, 'False-negative result. Wait at least 4 weeks post-antibiotics and 2 weeks post-PPI before retesting.', 4, 1789655696);
