INSERT INTO question_content (id, question_id, stem, lead_in, numeric_answer, numeric_tolerance, numeric_unit, decimal_places, calculator_allowed, calculation_working, created_at, updated_at) VALUES ('933a7d20-52f7-4ec5-a7d8-580e132b38bb', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'A 22-year-old female patient A 55-year-old male with recurrent gout attacks (3 flares in the last 6 months) has had his acute flare resolve. Serum urate is 480 micromol/L. eGFR is normal. (Case Ref: MUSCULOSKELETAL-1231). Relevant physiological and medication history have been reviewed.', 'What is the recommended approach for starting Urate Lowering Therapy (ULT)?', NULL, NULL, NULL, NULL, 1, NULL, 1789655696, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('651f85b4-0f61-463f-b8e6-335f55b71733', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'A', 'Initiate Allopurinol 100 mg daily with concurrent Colchicine 500 mcg od-bd as flare prophylaxis for up to 6 months; titrate monthly to urate < 300 micromol/L', 1, 'Correct. NICE NG219 recommends a treat-to-target strategy with target urate < 300 micromol/L. Prophylactic colchicine or NSAID prevents mobilization flares.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('78c27ab9-fcc5-4a54-8c1f-ec43b78b047c', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'B', 'Start Allopurinol 300 mg daily without flare prophylaxis cover', 0, 'Sub-optimal. Rapid unbuffered drop in serum urate triggers acute crystal shedding and severe flare, leading to patient non-adherence.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('1d463352-a877-4c15-ba99-6eaf3aac0118', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'C', 'Prescribe Colchicine in a patient taking strong P-gp / CYP3A4 inhibitors (e.g. Clarithromycin) with severe renal failure', 0, 'Fatal toxicity risk. Severe neuro-myopathy and bone marrow suppression occur rapidly.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a0dfeea7-5e70-425a-8517-810df8b28907', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'D', 'Withhold allopurinol indefinitely until patient has at least 10 documented attacks', 0, 'Deprecated historic under-treatment; modern guidance encourages early ULT to prevent irreversible joint erosion and tophi.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('c0f360cf-16f5-4ad6-ae0a-0da27dccb8a1', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'E', 'Check serum urate only once after 3 years without dose adjustment', 0, 'Fails treat-to-target principles. Monthly titration until urate < 300 micromol/L is mandatory.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('992dfdad-b354-4752-8398-c96d109b93c4', '1e10e6fb-7561-4478-80e6-1290ec4ee5d7', 'Allopurinol treat-to-target urate is < 300 micromol/L. Always provide anti-flare cover during initiation.', 'HLA-B*5801 testing is considered in Han Chinese and Korean ancestry due to severe cutaneous adverse reaction (SCAR) risk. Reference: NICE NG219: Gout: diagnosis and management (Section 1.5).', 'NICE NG219: Gout: diagnosis and management (Section 1.5)', 1789655696, 1789655696);
