INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a7b2e79e-6b07-4f6d-b2bf-96d1be08d834', 'aa680091-88dc-4039-8119-eb9755b5cebe', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('959f6a19-f7f2-4eed-ba5d-9f0bebab882b', 'aa680091-88dc-4039-8119-eb9755b5cebe', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('4fdffb05-2cfb-4f9a-a760-ba9d022ddd3a', 'aa680091-88dc-4039-8119-eb9755b5cebe', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789655696);
