INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('97b3d594-c5a1-4307-8a63-c68abb15cd04', '62f4c079-ae97-4559-972d-31c19df43c86', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789655696);
