INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('27f8c366-1e6a-4354-a84d-0374265e5aa1', '1a42a4b7-8f98-4199-8a6b-79e9b37f0a98', 'A', 'Hydrocortisone 1% cream applied thinly once or twice daily for up to 5 days', 1, 'Correct. Only mild topical corticosteroids (such as Hydrocortisone 0.5%-1%) should be used on the face and delicate skin folds to avoid skin atrophy, telangiectasia, and systemic absorption.', 0, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('692f1ad4-c53e-4ebf-b6a6-c8e1036b5760', '1a42a4b7-8f98-4199-8a6b-79e9b37f0a98', 'B', 'Betamethasone valerate 0.1% cream (potent) applied to the cheeks for 4 weeks', 0, 'Sub-optimal and dangerous. Potent steroids on facial skin cause irreversible perioral dermatitis and skin thinning.', 1, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('a5daf2cc-b5fe-4317-ae16-6e823e730ad7', '1a42a4b7-8f98-4199-8a6b-79e9b37f0a98', 'C', 'Clobetasol propionate 0.05% cream (very potent) applied generously under occlusion', 0, 'Strictly contraindicated. Very potent steroids on a child’s face can suppress the hypothalamic-pituitary-adrenal (HPA) axis.', 2, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('586f3004-6d56-444d-8a0d-e1448be261f6', '1a42a4b7-8f98-4199-8a6b-79e9b37f0a98', 'D', 'Mix topical steroid 50:50 with liquid paraffin in the dispensing tub', 0, 'Deprecated historical practice. Diluting steroids leads to unpredictable stability and microbial contamination.', 3, 1789655696);
INSERT INTO question_options (id, question_id, label, content, is_correct, rationale, sort_order, created_at) VALUES ('6fcf4b8f-1f8a-4890-839b-616bd5526014', '1a42a4b7-8f98-4199-8a6b-79e9b37f0a98', 'E', 'Apply emollient simultaneously without leaving a 20-30 minute interval', 0, 'Incorrect technique. Applying emollient at the exact same moment dilutes the active steroid and spreads it to unaffected skin.', 4, 1789655696);
INSERT INTO question_explanations (id, question_id, summary_takeaway, detailed_explanation, clinical_guidance_reference, created_at, updated_at) VALUES ('438863bc-fb9e-43d1-a522-1315bbccdcc3', '1a42a4b7-8f98-4199-8a6b-79e9b37f0a98', 'Use mild corticosteroids (Hydrocortisone 1%) for face and flexures. Allow 20-30 minutes between steroid and emollient.', 'One Fingertip Unit (FTU) is approximately 0.5 g and covers the area of two adult palms. Reference: NICE CG57 & BNF Chapter 13.', 'NICE CG57 & BNF Chapter 13', 1789655696, 1789655696);
